  "dsp.crossfeedUnavailablePure": "Χωρίς επίδραση όσο η λειτουργία PURE είναι ενεργή: η ρύθμιση διατηρείται και επανέρχεται μόλις απενεργοποιηθεί το PURE.",
  "v2.pure.veilEq": "Ο ισοσταθμιστής δεν έχει επίδραση στη λειτουργία PURE: το σήμα φεύγει ανέπαφο. Οι ρυθμίσεις σας διατηρούνται.",
  "v2.pure.veilCf": "Το crossfeed δεν έχει επίδραση στη λειτουργία PURE: το σήμα φεύγει ανέπαφο. Οι ρυθμίσεις σας διατηρούνται.",
  "v2.pure.veilExit": "Για να το χρησιμοποιήσετε, απενεργοποιήστε το PURE με το κουμπί PURE (ασπίδα) στη γραμμή αναπαραγωγής.",
  "dsp.crossfeedUnavailableProgressiveOff": "Χωρίς επίδραση προς το παρόν: σε ζώνη δικτύου, το crossfeed ταξιδεύει μαζί με τη ροή που επεξεργάζεται σε πραγματικό χρόνο. Στις Ρυθμίσεις, ορίστε το επίπεδο εμφάνισης σε «Για προχωρημένους» και μετά Ήχος → «Επεξεργασία στις συσκευές αναπαραγωγής δικτύου»: ορίστε το «EQ και επεξεργασία → δίκτυο» σε «Σε πραγματικό χρόνο».",
  "dsp.crossfeedUnavailableNoLpcm": "Χωρίς επίδραση: αυτή η συσκευή αναπαραγωγής δικτύου δεν δηλώνει ότι μπορεί να διαβάσει μη συμπιεσμένο PCM, τη μόνη μορφή που μεταφέρει το crossfeed. Η ρύθμιση διατηρείται και θα ισχύσει για άλλη έξοδο.",
  "dsp.crossfeedUnavailablePremium": "Χωρίς επίδραση: το crossfeed είναι μέρος του Tune Premium. Η ρύθμιση διατηρείται και θα επανέλθει με άδεια Premium.",
  "dsp.crossfeedUnavailablePlugin": "Χωρίς επίδραση: η επέκταση crossfeed δεν είναι εγκατεστημένη ή είναι απενεργοποιημένη. Ενεργοποιήστε την στις Ρυθμίσεις → Επεκτάσεις· η ρύθμιση διατηρείται.",
