  "onboarding.restoreLimits": "Δεν επαναφέρονται: το διακριτικό Discogs, οι λογαριασμοί υπηρεσιών streaming και τα αγαπημένα ραδιόφωνα — αυτά πρέπει να ρυθμιστούν ξανά.",
  "onboarding.restorePremium": "Το αυτόματο αντίγραφο ασφαλείας στο cloud — προφίλ, προτιμήσεις, αγαπημένα, λίστες αναπαραγωγής και ραδιόφωνα — είναι μέρος του Tune Premium. Βρίσκεται στις Ρυθμίσεις › Σύστημα › Αντίγραφο ασφαλείας στο cloud.",
