  "settings.devicesCleared": "Αφαιρέθηκαν {count} συσκευές",
  "settings.clearLibraryConfirm": "Εκκαθάριση ολόκληρης της βιβλιοθήκης; (κομμάτια, άλμπουμ, καλλιτέχνες)\nΤα παρακάτω θα ΧΑΘΟΥΝ και καμία σάρωση δεν τα αναδημιουργεί: περιεχόμενα λιστών αναπαραγωγής (τοπικά κομμάτια), βαθμολογίες άλμπουμ, σελιδοδείκτες, αγαπημένα, κασετίνες που συνθέσατε χειροκίνητα και επεξεργασίες άλμπουμ.\nΟι ζώνες, τα ραδιόφωνα, οι ρυθμίσεις και τα ονόματα των λιστών αναπαραγωγής διατηρούνται. Αντίγραφο ασφαλείας της βάσης δεδομένων δημιουργείται αυτόματα λίγο πριν (εκτός από PostgreSQL).\nΑντίθετα, με μια πλήρη σάρωση διατηρούνται οι κασετίνες και οι επεξεργασίες άλμπουμ.",
