  "settings.cleanupMovedGo": "Άνοιγμα εργαλείων βιβλιοθήκης",
  "settings.clearLibraryV2Hint": "Διαγράφει το ευρετήριο (κομμάτια, άλμπουμ, καλλιτέχνες). Μαζί του χάνονται: το περιεχόμενο των λιστών αναπαραγωγής, οι βαθμολογίες, οι σελιδοδείκτες, τα αγαπημένα, οι κασετίνες που συνθέσατε χειροκίνητα και οι επεξεργασίες άλμπουμ. Κανένα αρχείο μουσικής δεν διαγράφεται. Ένα αντίγραφο ασφαλείας της βάσης δεδομένων δημιουργείται ακριβώς πριν. Μια σάρωση επαναφέρει μόνο τα κομμάτια. Για να ανανεώσετε τη βιβλιοθήκη, εκτελέστε καλύτερα μια πλήρη σάρωση: διατηρεί τις κασετίνες και τις επεξεργασίες άλμπουμ.",
