  "renderer.wav24Hint": "Αποστολή πραγματικού WAV 24 bit. Προσφέρεται από προεπιλογή· απορρίπτεται μόνο όταν ο έλεγχος ανακάλυψης αποδεικνύει ότι αυτός ο renderer δεν δηλώνει ούτε audio/L24 ούτε audio/wav.",
  "renderer.depthCapNotRate": "Σημείωση: ο περιορισμός του βάθους bit δεν περιορίζει τη συχνότητα δειγματοληψίας. Ένα αρχείο 96 kHz/24 bit γίνεται 96 kHz/16 bit — εξακολουθεί να είναι 96 kHz. Αν ο renderer σας φτάνει έως τα 48 kHz, ρυθμίστε επίσης τη “Μέγιστη συχνότητα δειγματοληψίας”.",
  "renderer.flacAndWavSplitBySource": "Το “Επιβολή WAV” ισχύει μόνο για πηγές που δεν είναι FLAC (ALAC, AAC…) — παρακάμπτει τον αποκωδικοποιητή ALAC του renderer. Τα αρχεία FLAC σας εξακολουθούν να αποστέλλονται ως εγγενές FLAC.",
  "renderer.wav24Unproven": "Κανένας έλεγχος ανακάλυψης δεν έχει πετύχει ακόμη: τα 24 bit παραμένουν διαθέσιμα, αλλά τίποτα δεν επιβεβαιώνει ότι αυτή η συσκευή μπορεί να τα αναπαράγει. Πατήστε “Έλεγχος” παραπάνω.",
  "renderer.wav24Refused": "Ο έλεγχος ανακάλυψης απάντησε: αυτή η συσκευή δεν δηλώνει ούτε audio/L24 ούτε audio/wav. Τα 24 bit παραμένουν κλειστά — η αποστολή τους θα παρήγαγε σιωπή.",
  "renderer.startDelay": "Καθυστέρηση έναρξης",
  "renderer.startDelayHint": "Παύση πριν από την έναρξη της αναπαραγωγής, ώστε ένας ενισχυτής DLNA να προλάβει να κάνει buffering (βοηθά όταν τα πρώτα δευτερόλεπτα κολλάνε). 0 = προεπιλογή.",
  "renderer.probeFailed": "Δεν ήταν δυνατή η ανάγνωση των δυνατοτήτων του renderer. Ο διακομιστής δεν μπόρεσε να προσδιορίσει την ακριβή αιτία.",
  "renderer.probeOffline": "Ο renderer δεν έχει εντοπιστεί αυτή τη στιγμή. Βεβαιωθείτε ότι είναι ενεργοποιημένος και στο ίδιο δίκτυο.",
  "renderer.probeEmptySink": "Ο renderer απάντησε, αλλά δεν δημοσίευσε αξιοποιήσιμες δυνατότητες ήχου. Η αναπαραγωγή μπορεί να λειτουργεί παρ' όλα αυτά με αυτόματες ρυθμίσεις.",
  "renderer.probeSoapFailed": "Ο renderer εντοπίστηκε, αλλά το αίτημα δυνατοτήτων απέτυχε. Δοκιμάστε ξανά· αν ήδη παίζει, δεν χρειάζεται να αλλάξετε το δίκτυο.",
  "renderer.saveError": "Δεν ήταν δυνατή η αποθήκευση της ρύθμισης.",
  "renderer.saveConfig": "Αποθήκευση αυτής της διαμόρφωσης",
  "renderer.saveConfigHint": "Αυτές οι ρυθμίσεις εφαρμόζονται ήδη στη συσκευή τη στιγμή που κάνετε κλικ. Αυτό το κουμπί κρατά επιπλέον ένα μόνιμο αντίγραφο συνδεδεμένο με αυτήν τη συσκευή: μπορείτε να το επαναφέρετε από αυτήν την οθόνη ανά πάσα στιγμή.",
  "renderer.saveConfigNoKey": "Αυτή η ζώνη δεν έχει ούτε αναγνωριστικό εξόδου ούτε όνομα: δεν υπάρχει τίποτα με το οποίο να συνδεθεί μια αποθηκευμένη διαμόρφωση.",
  "renderer.configSavedOn": "Η διαμόρφωση αποθηκεύτηκε στις {date}",
  "renderer.configByName": "Χωρίς αναγνωριστικό εξόδου, αυτή η διαμόρφωση συνδέεται με το ΟΝΟΜΑ της ζώνης: η μετονομασία της θα την αποσυνέδεε.",
