  "renderer.resetCompat": "Επαναφορά συμβατότητας",
  "renderer.resetCompatHint": "Όταν αυτός ο renderer απορρίψει μια εντολή, το Tune θυμάται τη μορφή εντολής που δέχτηκε και την επαναχρησιμοποιεί, ακόμη και μετά από επανεκκίνηση. Η επαναφορά κάνει το επόμενο κομμάτι να ξεκινήσει ξανά με την πλήρη εντολή.",
