  "settings.dlnaCap16bitHint": "Ενεργοποιήστε το αν το hi-res (24 bit) δεν παράγει ήχο σε αυτόν τον renderer ενώ τα 16 bit λειτουργούν (Ruark R3). Επανακωδικοποιεί σε FLAC 16 bit αντί να στέλνει απευθείας 24 bit που ο renderer δεν μπορεί να αποκωδικοποιήσει.",
  "settings.alacPassthroughHint": "Αποστολή του ALAC ως έχει σε αυτόν τον renderer (bit-perfect, χωρίς μετατροπή σε FLAC). Ενεργοποιήστε το μόνο αν ο renderer αποκωδικοποιεί εγγενώς ALAC, διαφορετικά δεν θα υπάρχει ήχος.",
  "settings.aacPassthroughHint": "Αποστολή του AAC ως έχει σε αυτόν τον renderer αντί για μετατροπή σε FLAC. Η πηγή είναι ήδη με απώλειες, οπότε η μετατροπή δεν προσθέτει ποιότητα — απλώς καθυστερεί τον πρώτο ήχο. Ενεργοποιήστε το μόνο αν ο renderer αποκωδικοποιεί εγγενώς AAC, διαφορετικά δεν θα υπάρχει ήχος.",
  "settings.hqplayerHint": "Συνδέστε το Tune με το HQPlayer για upsampling και φίλτρα για audiophiles. Προεπιλεγμένη θύρα: 4321 (v4/v5) ή 8019 (v6).",
