  "settings.telemetryHint": "Αποστολή στατιστικών χρήσης για τη βελτίωση του Tune: αναγνωριστικό εγκατάστασης, έκδοση, πλατφόρμα, μεγέθη βιβλιοθήκης, συνδεδεμένες υπηρεσίες και μοντέλα συσκευών.",
  "settings.telemetryOffScope": "Η απενεργοποίησή της σταματά επίσης την κοινοποίηση και τη λήψη κοινοτικών μεταδεδομένων. Η επικύρωση της άδειας συνεχίζει να λειτουργεί, οπότε το Premium δεν χάνεται ποτέ.",
  "settings.communitySync": "Κοινοτική κοινοποίηση μεταδεδομένων",
  "settings.communitySyncHint": "Συμμετοχή στον κοινοτικό εμπλουτισμό: αντιστοίχιση MusicBrainz, είδη και συντελεστές (συνθέτης, μαέστρος, ερμηνευτές) που κοινοποιούνται μεταξύ διακομιστών Tune. Ανώνυμα — ποτέ τα αρχεία σας.",
  "settings.cloudListens": "Αποστολή των ακροάσεών μου στον λογαριασμό μου",
  "settings.cloudListensHint": "Προσθέτει τις ακροάσεις αυτού του διακομιστή στη σελίδα “Οι ακροάσεις μου” του λογαριασμού σας, μαζί με τους άλλους διακομιστές Tune σας. Για κάθε ακρόαση: η ημερομηνία, η διάρκεια, ένα αδιαφανές αναγνωριστικό προφίλ, ο τίτλος, ο καλλιτέχνης, το άλμπουμ και, όταν είναι γνωστά, το ISRC και το αναγνωριστικό MusicBrainz. Ποτέ οι διαδρομές των αρχείων σας, η διεύθυνση IP σας ή τα ονόματα των ζωνών σας. Απενεργοποιημένο από προεπιλογή.",
  "settings.cloudListensLink": "Δείτε τις ακροάσεις μου στο mozaiklabs.fr",
