  "settings.cloudListensConsentIntro": "Το Tune μπορεί να προσθέσει τις ακροάσεις αυτού του διακομιστή στον λογαριασμό σας στο mozaiklabs.fr. Τίποτα δεν αποστέλλεται μέχρι να απαντήσετε.",
  "settings.cloudListensConsentSentLabel": "Τι αποστέλλεται:",
  "settings.cloudListensConsentSent": "για κάθε ακρόαση, η ημερομηνία, η διάρκεια, ο τίτλος, ο καλλιτέχνης, το άλμπουμ, ένα αδιαφανές αναγνωριστικό προφίλ και, όταν είναι γνωστά, τα αναγνωριστικά ISRC και MusicBrainz.",
  "settings.cloudListensConsentNeverLabel": "Τι δεν αποστέλλεται ποτέ:",
