  "settings.cloudListensConsentBenefit": "Τι κερδίζετε: τη σελίδα “Οι ακροάσεις μου”, που συγκεντρώνει τις ακροάσεις όλων των διακομιστών Tune σας, καθώς και τις ακροάσεις της κοινότητας.",
  "settings.cloudListensConsentSettingsReminder": "Μπορείτε να αλλάξετε γνώμη ανά πάσα στιγμή στις Ρυθμίσεις › Σύστημα.",
  "settings.cloudListensConsentError": "Δεν ήταν δυνατή η αποθήκευση της απάντησής σας. Δοκιμάστε ξανά.",
  "settings.cloudListensConsentNo": "Όχι",
