  "settings.communityShare": "Κοινοποίηση των βαθμολογιών και των ακροάσεών μου στην κοινότητα (ανώνυμα)",
  "settings.communityShareHint": "Ξεχωριστό από τις “Οι ακροάσεις μου” και απενεργοποιημένο από προεπιλογή. Οι βαθμολογίες σας για άλμπουμ (χωρίς σχόλιο) και οι ακροάσεις που λαμβάνει ο λογαριασμός σας ΜΕΤΑ την ενεργοποίηση μπαίνουν σε δημόσια, ανώνυμα σύνολα, που εμφανίζονται στη σελίδα ενός άλμπουμ από τρία διαφορετικά άτομα και πάνω. Κανένα ατομικό δεδομένο δεν εμφανίζεται ποτέ. Η απενεργοποίηση αφαιρεί αμέσως τη συνεισφορά σας.",
  "settings.communityMeasuresReceive": "Λήψη αποτελεσμάτων ανάλυσης από την κοινότητα",
  "settings.communityMeasuresReceiveHint": "Απενεργοποιημένο από προεπιλογή. Για τα αρχεία FLAC σας, ο διακομιστής ζητά από το mozaiklabs.fr τιμές ReplayGain, δυναμικού εύρους και ακουστικά αποτυπώματα που έχουν ήδη μετρηθεί στο ακριβώς ίδιο σήμα από τουλάχιστον δύο άλλες εγκαταστάσεις. Συμπληρώνουν μόνο ό,τι λείπει: οι ετικέτες σας και οι δικές σας μετρήσεις δεν αντικαθίστανται ποτέ. Ο ιστότοπος λαμβάνει μόνο ένα σύντομο πρόθεμα, ποτέ τη λίστα των αρχείων σας.",
  "settings.communityMeasuresContribute": "Κοινοποίηση των αποτελεσμάτων ανάλυσής μου στην κοινότητα",
  "settings.communityMeasuresContributeHint": "Απενεργοποιημένο από προεπιλογή. Ο διακομιστής στέλνει στον ιστότοπο μόνο τις μετρήσεις που έκανε ο ίδιος στα αρχεία FLAC σας (ReplayGain, δυναμικό εύρος, ακουστικό αποτύπωμα), ταυτοποιημένες από την υπογραφή του σήματός τους. Δεν αποστέλλεται καμία διαδρομή, τίτλος, όνομα αρχείου ή λογαριασμός: ο διακομιστής ταυτοποιείται με τον αριθμό εγκατάστασής του. Η απενεργοποίηση διαγράφει ό,τι έχει αποσταλεί.",
