  "zoneConfig.cardChannelsHint": "Με τη σειρά των καναλιών του κομματιού (αριστερό, δεξί, έπειτα η σειρά του αρχείου). Εφαρμόζεται σε αποκλειστική λειτουργία ASIO, από το επόμενο κομμάτι ή όταν ξεκινήσει ξανά η αναπαραγωγή. Ένας οδηγός ASIO εξυπηρετεί μία ζώνη τη φορά: δύο ζώνες στην ίδια κάρτα εναλλάσσονται.",
