  "zoneConfig.crossfadeLabel": "Crossfade",
  "zoneConfig.crossfadeHint": "Επικαλύπτει το τέλος ενός κομματιού με την αρχή του επόμενου, μεταξύ δύο διαφορετικών άλμπουμ (σε τυχαία σειρά, για παράδειγμα). 0 = ανενεργό. Ποτέ μεταξύ δύο κομματιών του ίδιου άλμπουμ, ούτε σε λειτουργία PURE.",
