  "zoneConfig.crossfadeOff": "Ανενεργό",
  "zoneConfig.crossfadeExclusive": "Μη διαθέσιμο σε αποκλειστική λειτουργία: αυτή η έξοδος συνδέει τα κομμάτια χωρίς κενά, αλλά δεν τα επικαλύπτει.",
  "zoneConfig.dsdLabel": "Λειτουργία DSD",
  "zoneConfig.fixedVolumeNetElsewhere": "Η σταθερή ένταση μιας ζώνης δικτύου ορίζεται στις Ρυθμίσεις › Ρυθμίσεις ανά ζώνη: στέλνει 100 % στη συσκευή και ζητά επιβεβαίωση.",
  "zoneConfig.monoDesc": "Αν είναι συνδεδεμένο μόνο ένα ηχείο ή αν ένα κανάλι μένει σιωπηλό, ό,τι έχει μιξαριστεί μόνο στο άλλο κανάλι εξαφανίζεται: μια φωνή, μια κιθάρα, μερικές φορές η μισή ορχήστρα.",
  "zoneConfig.monoLabel": "Άθροιση του αριστερού και του δεξιού καναλιού και αποστολή αυτής της μίξης και στα δύο",
  "zoneConfig.monoLocalOnly": "Αυτή η ζώνη δεν χρησιμοποιεί τοπική έξοδο: η ρύθμιση αποθηκεύεται, αλλά δεν θα αλλάξει τίποτα εδώ. Η άθροιση γίνεται στην αλυσίδα ήχου του διακομιστή, η οποία υπάρχει μόνο για κάρτα ήχου ή DAC συνδεδεμένο στον διακομιστή.",
  "zoneConfig.channelsTitle": "Κανάλια",
  "zoneConfig.channelsFollow": "Σύμφωνα με τη συσκευή",
  "zoneConfig.channelsUnavailableNonLocal": "Έξοδος δικτύου: το Tune δεν ορίζει το ίδιο τον αριθμό καναλιών — η συσκευή διαπραγματεύεται τη μορφή της και αποκωδικοποιεί τη ροή. Αυτό το κλείδωμα δεν λέει τίποτα για το τι μπορεί να αναπαράγει η συσκευή σας: ένας πολυκαναλικός ενισχυτής παραμένει πολυκαναλικός.",
  "zoneConfig.channelsUnavailableBeyondDevice": "Η συσκευή αναφέρει λιγότερα κανάλια από τη διάταξη που επιλέξατε.",
  "zoneConfig.channelsNetworkCeiling": "Έξοδος δικτύου: η επιλογή ισχύει όταν το Tune αποκωδικοποιεί τη ροή — ένα πολυκαναλικό κομμάτι της βιβλιοθήκης σας μειώνεται στον επιλεγμένο αριθμό καναλιών. Το Tune δεν προσθέτει ποτέ κανάλια, μια ροή DSD που σερβίρεται ως έχει μένει ανέγγιχτη, και αν η συσκευή ανακοινώνει λιγότερα κανάλια, υπερισχύει η συσκευή.",
