  "settings.analysisUnthrottleHint": "Ανενεργό από προεπιλογή. Χωρίς αναγνώσιμη θερμοκρασία (συχνά στα Windows), οι αναλύσεις στο παρασκήνιο περιορίζονται σε ένα αρχείο τη φορά για προφύλαξη. Όταν είναι ενεργό, διατηρούν τη ρυθμισμένη ταχύτητα. Μια υψηλή θερμοκρασία που διαβάζεται πραγματικά εξακολουθεί να σταματά τις αναλύσεις. Η αναπαραγωγή δεν περιορίζεται ποτέ.",
  "settings.analysisUnthrottleConfirm": "Το Tune δεν μπορεί να διαβάσει τη θερμοκρασία αυτού του επεξεργαστή: δεν θα μπορεί να σταματήσει τις αναλύσεις αν το μηχάνημα ζεσταθεί. Ένα κακώς αεριζόμενο μηχάνημα μπορεί να υπερθερμανθεί ή ακόμη και να σβήσει. Άρση του περιορισμού παρ' όλα αυτά;",
