  "outputModule.notLinkedTitle": "Η λειτουργική μονάδα {module} είναι εγκατεστημένη, αλλά ανενεργή.",
  "outputModule.notLinkedBody": "Δεν πρόκειται για πρόβλημα εγκατάστασης και δεν φταίει το κλειδί άδειας χρήσης σας. Τα δικαιώματα για τις επί πληρωμή μονάδες συνδέονται με τον λογαριασμό σας Mozaiklabs, ποτέ με το κλειδί άδειας: όσο δεν έχει συνδεθεί λογαριασμός σε αυτόν τον διακομιστή, η μονάδα δεν μπορεί να λάβει το δικαίωμά της και δεν θα εμφανίζει συσκευές. Συνδέστε τον λογαριασμό σας στις Ρυθμίσεις ▸ Σύστημα ▸ Cloud.",
  "outputModule.notLinkedAction": "Σύνδεση του λογαριασμού μου Mozaiklabs",
  "outputModule.notOwnedTitle": "Η λειτουργική μονάδα {module} δεν περιλαμβάνεται στα δικαιώματα του λογαριασμού σας Mozaiklabs.",
  "outputModule.notOwnedBody": "Ο λογαριασμός σας είναι συνδεδεμένος και αυτός ο διακομιστής μπόρεσε να διαβάσει τα δικαιώματά σας: αυτή η μονάδα δεν περιλαμβάνεται σε αυτά. Πρόκειται για επί πληρωμή μονάδα που πρέπει να προστεθεί στον λογαριασμό σας — η εγκατάσταση του διακομιστή σας δεν φταίει.",
  "outputModule.notOwnedAction": "Προβολή των μονάδων",
  "outputModule.unknownTitle": "Η λειτουργική μονάδα {module} είναι ανενεργή.",
  "outputModule.unknownBody": "Ο διακομιστής αρνείται να ενεργοποιήσει αυτή τη μονάδα για έναν λόγο που αυτή η έκδοση της διεπαφής δεν μπορεί ακόμη να προσδιορίσει. Η αναφορά διάγνωσης περιέχει τις λεπτομέρειες.",
