  "v2.health.drUnavailable": "{n} κομμάτια παραλείφθηκαν οριστικά: η μέτρηση δεν μπόρεσε να ολοκληρωθεί σε αυτά τα αρχεία.",
  "v2.health.drGaugeMeasurable": "Ο δείκτης αφορά τα {n} κομμάτια που μπορούν να μετρηθούν.",
  "v2.health.drOversized": "{n} κομμάτια εξαιρέθηκαν από τη μέτρηση: πολύ μεγάλα για τον προϋπολογισμό μνήμης της ανάλυσης (αρχεία υψηλής ανάλυσης ή DSD μεγαλύτερα από λίγα λεπτά).",
  "v2.health.drWithoutFile": "{n} κομμάτια χωρίς δικό τους αρχείο (εικόνες CUE): η μέτρηση διαβάζει ολόκληρο αρχείο, όχι διαχωρισμένο κομμάτι.",
  "v2.health.drOutOfScope": "{n} κομμάτια χωρίς DR βρίσκονται σε φάκελο που εξαιρείται από την ανάλυση: κανένα πέρασμα δεν θα τα μετρήσει όσο ισχύει η εξαίρεση.",
  "v2.health.drLineSidecar": "{n} από {t} κομμάτια — {m} μετρήθηκαν από το Tune, {g} διαβάστηκαν από ετικέτες, {s} διαβάστηκαν από αρχεία foo_dr.txt",
  "v2.health.drQueuedBeforeFingerprints": "{n} κομμάτια σε αναμονή. Το δυναμικό εύρος εκτελείται αμέσως μετά το ReplayGain, πριν από τα αποτυπώματα και το CLAP.",
  "v2.health.drQueuedFirst": "{n} κομμάτια σε αναμονή. Το δυναμικό εύρος εκτελείται πρώτο, πριν από το ReplayGain, τα αποτυπώματα και το CLAP.",
  "v2.health.drMeasuredByRg": "{n} κομμάτια δεν έχουν εξεταστεί ακόμη από το ReplayGain: το πέρασμά του θα μετρήσει το δυναμικό τους εύρος στην ίδια αποκωδικοποίηση, όποια σειρά κι αν επιλεγεί.",
  "v2.health.drSidecarLast": "Αναφορές foo_dr.txt: {d} φάκελοι ελέγχθηκαν, {w} κομμάτια συμπληρώθηκαν στο τελευταίο πέρασμα.",
