  "v2.hint.ingestRule": "Πώς το Tune αρχειοθετεί ό,τι εισάγετε. ΔΕΝ ισχύει για φακέλους που έχετε ήδη δηλώσει: αυτοί διαβάζονται εκεί όπου βρίσκονται και δεν μετακινούνται ποτέ.",
  "v2.hint.dbNotAttached": "Η βάση δεδομένων δεν είναι συνδεδεμένη: η βιβλιοθήκη και οι ζώνες δεν μπορούν ούτε να διαβαστούν ούτε να εγγραφούν. Διορθώστε το πριν από οποιαδήποτε άλλη διάγνωση.",
  "v2.hint.csvExport": "Ένα στιγμιότυπο της βιβλιοθήκης σε CSV, για υπολογιστικό φύλλο ή απογραφή. Η εξαγωγή δεν αλλάζει τίποτα.",
  "v2.hint.lanAddresses": "Αυτές οι διευθύνσεις ανοίγουν το Tune από άλλη συσκευή στο ίδιο δίκτυο — τηλέφωνο, tablet, άλλο υπολογιστή. Δεν βγαίνουν ποτέ από το τοπικό σας δίκτυο.",
  "v2.hint.tokensUse": "χρησιμοποιούνται για τον εμπλουτισμό των μεταδεδομένων και το scrobbling.",
  "v2.hint.spotifyConnect": "Εμφανίζει μια ζώνη ως ηχείο στην εφαρμογή Spotify: εμφανίζεται στη λίστα συσκευών και η αναπαραγωγή καταλήγει σε αυτή τη ζώνη.",
  "v2.hint.analysisCost": "Η ανάλυση ακούει δέκα δευτερόλεπτα από κάθε κομμάτι για να υπολογίσει το ηχητικό του αποτύπωμα. Τρέχει στο παρασκήνιο, μία φορά ανά κομμάτι. Ο ρυθμός ορίζει πόσο από το μηχάνημα χρησιμοποιεί: όσο πιο γρήγορος, τόσο περισσότερο δουλεύει ο επεξεργαστής.",
  "v2.hint.licenseElsewhere": "Αυτή η άδεια χρήσης είναι αυτή τη στιγμή ενεργή σε άλλον διακομιστή. Οι λειτουργίες Premium αναστέλλονται εδώ όσο παραμένει ανοιχτή εκεί.",
  "v2.hint.ticketsAccount": "Η παρακολούθηση των αιτημάτων υποστήριξης συνδέεται με τον",
  "v2.hint.noKeyNoTickets": ". Δεν έχει καταχωριστεί κλειδί σε αυτόν τον διακομιστή, οπότε δεν υπάρχει νήμα για εμφάνιση.",
  "v2.hint.processingFromSettings": "Οι επεξεργασίες ξεκινούν από τις Ρυθμίσεις — Βιβλιοθήκη και Μεταδεδομένα.",
  "v2.hint.serverUnreachableDot": "Ο διακομιστής δεν είναι προσβάσιμος.",
