  "v2.zone.browserPlayHere": "Αναπαραγωγή σε αυτή τη συσκευή",
  "v2.set.browserZoneDuplicates": "Υπάρχουν ήδη {n} ζώνες προγράμματος περιήγησης. Είναι εναλλάξιμες — αρκεί μία.",
  "v2.set.peakMeter": "Μετρητής κορυφών",
  "v2.set.peakMeterHint": "Μόνο προβολή — το σήμα δεν αλλάζει. Η γραμμή αναπαραγωγής εμφανίζει μόνο τις λυχνίες: τα δύο ραβδογράμματα είναι πολύ φαρδιά γι' αυτήν.",
  "v2.set.barVu": "Γραμμή αναπαραγωγής με VU-μετρητές",
  "v2.set.barVuHint": "Μόνο προβολή — το σήμα δεν αλλάζει. Δύο καντράν με βελόνα δεξιά και αριστερά από τα χειριστήρια· αντικαθιστούν τις λυχνίες κορυφής και το μίνι φάσμα. Σε στενή γραμμή, επανέρχεται η συνηθισμένη γραμμή.",
