  "v2.hint.volumeDisplay": "Πώς εμφανίζεται η ένταση. Τα ντεσιμπέλ δείχνουν την πραγματική απολαβή· το ποσοστό είναι κλίμακα προβολής, όχι μέτρηση.",
  "v2.hint.ingestMode": "🔴 Η «Μετακίνηση» αφαιρεί το αρχείο από την αρχική του θέση. Η «Αντιγραφή» το αφήνει εκεί και καταλαμβάνει διπλάσιο χώρο.",
  "v2.hint.audioBackend": "Ο οδηγός μέσω του οποίου βγαίνει ο ήχος. Το ASIO χρειάζεται οδηγό από τον κατασκευαστή· χωρίς αυτόν η έξοδος μένει βουβή.",
  "v2.hint.wasapiMode": "Σε αποκλειστική λειτουργία το Tune δεσμεύει την κάρτα ήχου μόνο για τον εαυτό του: η ροή βγαίνει bit-perfect, αλλά οι άλλες εφαρμογές σιωπούν.",
