  "v2.circle.scene.loc.what": "Ανενεργό από προεπιλογή. Ορίζετε εσείς την πόλη σας, στην υδρόγειο ή πληκτρολογώντας την, και της δίνετε όποιο όνομα θέλετε. Τη βλέπουν οι αποδεκτές επαφές σας, στρογγυλοποιημένη σε περίπου 50 km· εμφανίζεται επίσης ως ανώνυμη κουκκίδα στον δημόσιο χάρτη (χωρίς όνομα, στρογγυλοποιημένη σε περίπου 110 km), εκτός αν αποσυρθείτε από αυτόν. Ποτέ διεύθυνση, ποτέ η θέση της συσκευής σας.",
  "v2.circle.scene.public.noticeTitle": "Νέο: ο δημόσιος χάρτης",
  "v2.circle.scene.public.notice": "Όταν ορίσατε την πόλη σας, μόνο οι αποδεκτές επαφές σας μπορούσαν να τη δουν. Τώρα εμφανίζεται επίσης ως ανώνυμη κουκκίδα στον δημόσιο χάρτη της προβολής Κόσμος: χωρίς όνομα, χωρίς ψευδώνυμο, χωρίς βιβλιοθήκη, στρογγυλοποιημένη σε περίπου 110 km και μόνο σε περιοχές με τουλάχιστον 3 μέλη. Οι επαφές σας τη βλέπουν όπως πριν.",
