  "dsp.crossfeedReplacedByPro": "Το Crossfeed Pro επεξεργάζεται αυτή τη ζώνη: το ενσωματωμένο crossfeed είναι απενεργοποιημένο εδώ. Τα δύο δεν συνδυάζονται ποτέ.",
  "v2.pure.veilCfPro": "Το Crossfeed Pro δεν έχει καμία επίδραση σε λειτουργία PURE: το σήμα φεύγει ανέπαφο. Οι ρυθμίσεις σας διατηρούνται.",
