  "cloudBackup.title": "Αντίγραφο ασφαλείας στο cloud",
  "cloudBackup.intro": "Το Tune δημιουργεί αντίγραφα ασφαλείας των προσαρμογών σας στη Mozaiklabs, κρυπτογραφημένα σε αυτόν τον διακομιστή με κλειδί που η Mozaiklabs δεν γνωρίζει: ρυθμίσεις, ζώνες, προφίλ και προτιμήσεις, ισοσταθμιστές, αγαπημένα, λίστες αναπαραγωγής και ραδιόφωνα. Ποτέ τη βιβλιοθήκη σας, ούτε κωδικούς πρόσβασης και διακριτικά των υπηρεσιών, με μία εξαίρεση: το διακριτικό Discogs, που ταξιδεύει κρυπτογραφημένο μαζί με τα υπόλοιπα. Διατηρούνται έως τρία στιγμιότυπα ανά μηχάνημα και έως πέντε μηχανήματα ανά λογαριασμό· τα παλαιότερα αφαιρούνται.",
  "cloudBackup.statePremium": "Το αντίγραφο ασφαλείας στο cloud είναι μέρος του Tune Premium.",
  "cloudBackup.stateNotLinked": "Συνδέστε αυτόν τον διακομιστή με τον λογαριασμό σας Mozaiklabs (ενότητα Cloud, ακριβώς από πάνω) για να χρησιμοποιήσετε το αντίγραφο ασφαλείας.",
